export function usageNumbers(used,limit){if(!Number.isFinite(used)||used<0||!Number.isFinite(limit)||limit<=0)return null;return {used,limit,free:Math.max(0,limit-used),percent:used/limit*100};}
export function install(ctx){
 let busy=false,request=0;
 const bytes=n=>!Number.isFinite(n)?'Indisponível':n>=1e9?(n/1e9).toLocaleString('pt-BR',{maximumFractionDigits:2})+' GB':n>=1e6?(n/1e6).toLocaleString('pt-BR',{maximumFractionDigits:2})+' MB':(n/1e3).toLocaleString('pt-BR',{maximumFractionDigits:1})+' KB';
 const card=(title,used,limit,note)=>{const n=usageNumbers(used,limit);return `<article class="panel usage-card"><h2>${title}</h2><div class="usage-value">${bytes(used)}</div><small>Espaço ocupado</small>${n?`<progress value="${Math.min(n.percent,100)}" max="100" aria-label="Uso de ${title}"></progress><p><strong>${bytes(n.free)}</strong> disponíveis na referência de ${bytes(limit)}</p><p>${n.percent.toLocaleString('pt-BR',{maximumFractionDigits:2})}% utilizado${n.percent>=80?' · atenção ao limite':''}</p>`:''}<p class="muted">${note}</p></article>`};
 function usagePage(){if(!ctx.profile?.is_owner||!ctx.profile?.active){ctx.toast('Área exclusiva do Mestre Criador.');return}busy=false;ctx.shell(`${ctx.head('Uso e armazenamento','Exclusivo do Mestre Criador · dados, anexos e aplicativo.')}<p class="note">Espaço de armazenamento não é memória RAM. Os limites abaixo são referências do plano gratuito, verificados em 12/11/2026; não contratam serviços nem autorizam cobrança. O painel oficial de cada serviço é a referência final para cotas e consumo.</p><button class="secondary" id="usage-refresh">Atualizar medições</button><p id="usage-status" role="status" aria-live="polite">Consultando os serviços…</p><div id="usage-results" class="usage-grid"></div><div class="usage-links"><a href="https://supabase.com/dashboard/org/alcfgsnksopwfgxjrrqo" target="_blank" rel="noopener noreferrer">Painel do Supabase</a><a href="https://github.com/contatoavelontextil-sketch/sistema-avelon" target="_blank" rel="noopener noreferrer">Repositório no GitHub</a><a href="https://supabase.com/docs/guides/platform/billing-on-supabase" target="_blank" rel="noopener noreferrer">Limites do Supabase</a><a href="https://docs.github.com/en/pages/getting-started-with-github-pages/github-pages-limits" target="_blank" rel="noopener noreferrer">Limites do GitHub Pages</a></div><section class="panel"><div class="panelbody"><h2>O que estes números significam?</h2><p>Supabase: o tamanho físico do banco inclui estruturas internas e índices. O total das tabelas da aplicação aparece à parte. O espaço livre é uma estimativa frente a 500 MB, não uma medição de disco disponível ou a cota oficial faturada.</p><p>Anexos: a soma dos metadados dos arquivos de todos os buckets do projeto é comparada à referência de 1 GB. Arquivos arquivados ainda ocupam espaço. A franquia do Storage pode ser compartilhada com outros projetos da organização.</p><p>GitHub: o repositório inclui código e histórico. Não existe uma cota simples de “memória livre” por repositório. O aplicativo publicado tem referência de 1 GB; o tamanho do pacote abaixo é medido na preparação da versão, antes dos ajustes finais da publicação.</p><p>Tráfego mensal, minutos do Actions, RAM e consumo de outros projetos não são medidos aqui. Confira os painéis oficiais para acompanhar essas cotas.</p></div></section>`);ctx.$('#usage-refresh').onclick=refresh;refresh();}
 async function refresh(){if(busy||!ctx.profile?.is_owner||ctx.current!=='usage')return;busy=true;const seq=++request;const button=ctx.$('#usage-refresh');button.disabled=true;ctx.$('#usage-status').textContent='Consultando os serviços…';
  const read=async url=>{const r=await fetch(url,{credentials:'omit',cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Consulta indisponível');return r.json()};
  const results=await Promise.allSettled([ctx.rpc('owner_storage_usage'),read('https://api.github.com/repos/contatoavelontextil-sketch/sistema-avelon'),read('usage-assets.json')]);
  if(seq!==request||ctx.current!=='usage'||!ctx.profile?.is_owner)return;
  const [db,git,site]=results;let html='';
  if(db.status==='fulfilled'){const d=db.value;html+=card('Supabase · banco',d.database_bytes,500e6,'Estimativa física do banco. Tabelas da aplicação: '+bytes(d.app_tables_bytes)+'.')+card('Supabase · arquivos',d.storage_bytes,1e9,Number(d.storage_objects||0)+' arquivos contabilizados nos metadados do projeto.');}
  else html+=card('Supabase · banco',null,null,'Medição indisponível. Tente atualizar ou consulte o painel oficial.')+card('Supabase · arquivos',null,null,'Medição indisponível. Não interprete como espaço vazio.');
  html+=git.status==='fulfilled'?card('GitHub · repositório',Number.isFinite(git.value.size)?git.value.size*1024:null,null,'Tamanho informado pela API pública do GitHub; pode atualizar com atraso. Espaço livre: não se aplica a uma cota simples por repositório.'):card('GitHub · repositório',null,null,'API pública indisponível ou limitada. Consulte o repositório.');
  html+=site.status==='fulfilled'?card('GitHub Pages · aplicativo',site.value.bytes,1e9,'Estimativa do pacote da versão, em '+ctx.esc(new Date(site.value.measured_at).toLocaleString('pt-BR'))+'. Não inclui histórico do repositório.'):card('GitHub Pages · aplicativo',null,null,'Medição do pacote indisponível.');
  ctx.$('#usage-results').innerHTML=html;ctx.$('#usage-status').textContent='Consulta concluída em '+new Date().toLocaleString('pt-BR')+(results.some(r=>r.status==='rejected')?' · algumas medições não estão disponíveis.':'.');busy=false;button.disabled=false;
 }
 Object.assign(ctx,{usagePage});
}
